ruleHooks.extraMethods:
; Segmentos cadastrados (F7): tabela(segmento)=descrição
;
; set sc=$$ObterTabSegmento^WDOMTESTECOM100RG(codEmpresa,.tabela)
ObterTabSegmento(codEmpresa,tabela)	;
$$$VAR
new segmento
;
kill tabela
set segmento=""
for  set segmento=$order(^WDOMTESTECOMCFG(1,codEmpresa,1,segmento)) quit:segmento=""  do
. set tabela(segmento)=$piece($get(^WDOMTESTECOMCFG(1,codEmpresa,1,segmento)),Z,3)
;
quit $$$OK
;
; Descrição da máscara sintética de saída (valida e devolve a máscara editada)
;
; set sc=$$ValidarMascaraSintetica^WDOMTESTECOM100RG(codEmpresa,mascara,.mascaraEditada)
ValidarMascaraSintetica(codEmpresa,mascara,mascaraEditada)	;
$$$VAR
new sc,codItem,mascaraRet,mascaraRed,mascaraEdtRed,tipoMascara,niveis,nivelValor
;
set mascaraEditada=""
set sc=$$ValidarMascaraItem^CCCGIRG012(codEmpresa,"S",mascara,0,2,1,.codItem,.mascaraEditada,.mascaraRet,.mascaraRed,.mascaraEdtRed,.tipoMascara,.niveis,.nivelValor)
;
quit sc
